INSERT INTO `news` (`id`, `title`, `author`, `category_id`, `status`, `body`, `image`, `views`, `created_at`, `updated_at`) VALUES
(1, 'ChatGPT Gets Real-Time Voice Mode in New Update', 'Aibek Seitkali', 1, 'published', 'OpenAI has rolled out a new real-time voice mode for ChatGPT, allowing users to have natural spoken conversations with the AI. The update reduces latency significantly and introduces emotion detection capabilities.', 'chatgpt_voice.png', 3820, '2026-02-02 10:00:00', '2026-02-02 10:00:00'),
(2, 'Google DeepMind Releases Gemini 2.0 Ultra', 'Dinara Akhmetova', 1, 'published', 'Google DeepMind has announced Gemini 2.0 Ultra, the companys most capable multimodal model to date. The model outperforms competitors on coding, math, and scientific reasoning benchmarks.', 'gemini_ultra.png', 2950, '2026-03-03 10:00:00', '2026-03-03 10:00:00'),
(3, 'AI Coding Assistants Now Write 40% of All Code at Major Tech Firms', 'Nursultan Nurmagambetov', 1, 'published', 'A new industry report reveals that AI-powered coding tools such as GitHub Copilot and Cursor are responsible for generating over 40% of code at leading technology companies, reshaping developer workflows.', 'ai_coding.png', 4110, '2026-04-04 10:00:00', '2026-04-04 10:00:00'),
(4, 'Open-Source LLM Llama 4 Tops Leaderboard Benchmarks', 'Madina Bekova', 1, 'draft', 'Metas latest open-source language model Llama 4 has topped several independent benchmark leaderboards, challenging closed-source models from OpenAI and Anthropic.', 'llama4.png', 980, '2026-01-05 10:00:00', '2026-01-05 10:00:00'),
(5, 'React 20 Announced with Built-in Server Components', 'Yerlan Sultanov', 2, 'published', 'The React team has officially announced React 20, featuring native server components support without requiring a framework wrapper. The release also includes a new concurrent rendering engine.', 'react20.png', 3340, '2026-02-06 10:00:00', '2026-02-06 10:00:00'),
(6, 'Laravel 12 Released with Automatic API Versioning', 'Zarina Karimova', 2, 'published', 'Laravel 12 has landed with several developer-experience improvements including automatic API versioning, a revamped Artisan CLI, and native support for async jobs via Fibers.', 'laravel12.png', 2760, '2026-03-07 10:00:00', '2026-03-07 10:00:00'),
(7, 'CSS Grid Level 3 Spec Finalized by W3C', 'Damir Tulegenov', 2, 'published', 'The W3C has finalized the CSS Grid Level 3 specification, introducing masonry layout as a native CSS feature. Developers will no longer need JavaScript libraries to create dynamic grid layouts.', 'css_grid3.png', 1890, '2026-04-08 10:00:00', '2026-04-08 10:00:00'),
(8, 'Bun 2.0 Outperforms Node.js in New Benchmarks', 'Aigerim Abdullina', 2, 'published', 'Bun 2.0 has been released with significant performance improvements. Independent benchmarks show it handles over 2x more HTTP requests per second than Node.js in comparable configurations.', 'bun2.png', 2540, '2026-01-09 10:00:00', '2026-01-09 10:00:00'),
(9, 'Critical Zero-Day Found in OpenSSL 3.x', 'Ruslan Ospanov', 3, 'published', 'Security researchers have disclosed a critical zero-day vulnerability in OpenSSL 3.x that could allow remote code execution. A patch has been released and administrators are urged to update immediately.', 'openssl_vuln.png', 5200, '2026-02-10 10:00:00', '2026-02-10 10:00:00'),
(10, 'Phishing Attacks Using AI-Generated Voice Rise 300%', 'Saule Dzhaksybekova', 3, 'published', 'Cybersecurity firm Recorded Future reports a 300% year-on-year increase in voice phishing attacks powered by AI voice cloning technology, targeting corporate finance departments.', 'ai_phishing.png', 4670, '2026-03-11 10:00:00', '2026-03-11 10:00:00'),
(11, 'NIST Releases Post-Quantum Cryptography Standards', 'Bekzat Kenzhebaev', 3, 'published', 'The US National Institute of Standards and Technology has officially published its first set of post-quantum cryptography standards, marking a major milestone in preparing digital infrastructure for the quantum era.', 'pqc_standards.png', 3100, '2026-04-12 10:00:00', '2026-04-12 10:00:00'),
(12, 'Password Managers Under Scrutiny After LastPass Incident Follow-Up', 'Ainur Mukhanova', 3, 'draft', 'Following the 2022 LastPass breach, security auditors have published a follow-up report examining how stolen vault data has been exploited and what lessons the industry should adopt.', 'password_managers.png', 1450, '2026-01-13 10:00:00', '2026-01-13 10:00:00'),
(13, 'Apple Announces iOS 20 with AI-Powered App Suggestions', 'Marat Iskakov', 4, 'published', 'Apples iOS 20 introduces a deeply integrated AI layer that learns user habits to proactively suggest apps, shortcuts, and settings adjustments throughout the day.', 'ios20.png', 3890, '2026-02-14 10:00:00', '2026-02-14 10:00:00'),
(14, 'Flutter 4.0 Brings Native Desktop Performance on All Platforms', 'Gulnara Yesimova', 4, 'published', 'Google has released Flutter 4.0 with a rewritten rendering engine that achieves near-native performance on Windows, macOS, and Linux, closing the gap with platform-specific frameworks.', 'flutter4.png', 2220, '2026-03-15 10:00:00', '2026-03-15 10:00:00'),
(15, 'Android 16 Introduces Adaptive Battery 3.0', 'Timur Baimanov', 4, 'published', 'Android 16 debuts Adaptive Battery 3.0, which uses on-device machine learning to dynamically throttle background processes, extending battery life by up to 25% in real-world tests.', 'android16.png', 1780, '2026-04-16 10:00:00', '2026-04-16 10:00:00'),
(16, 'AWS Launches New Central Asia Data Center in Almaty', 'Raushan Satova', 5, 'published', 'Amazon Web Services has inaugurated its first data center region in Central Asia, located in Almaty. The region offers three availability zones and full compliance with Kazakhstani data localization laws.', 'aws_almaty.png', 6100, '2026-01-17 10:00:00', '2026-01-17 10:00:00'),
(17, 'Kubernetes 1.32 Simplifies Multi-Cluster Management', 'Azamat Zhumabekov', 5, 'published', 'Kubernetes 1.32 introduces a new multi-cluster API that significantly simplifies managing workloads across multiple clusters, reducing configuration overhead for platform engineering teams.', 'k8s_132.png', 2870, '2026-02-18 10:00:00', '2026-02-18 10:00:00'),
(18, 'Cloudflare Workers Now Support Python Natively', 'Nurgul Askarova', 5, 'published', 'Cloudflare has added native Python support to its Workers serverless platform, allowing developers to deploy Python code at the edge without transpilation or bundling steps.', 'cf_python.png', 2340, '2026-03-19 10:00:00', '2026-03-19 10:00:00'),
(19, 'Terraform 2.0 Drops HCL in Favor of YAML Configuration', 'Dias Seidaliev', 5, 'draft', 'HashiCorp has released a major Terraform 2.0 preview that replaces HCL with YAML-based configuration files, aiming to lower the barrier to entry for teams already familiar with Kubernetes manifests.', 'terraform2.png', 890, '2026-04-20 10:00:00', '2026-04-20 10:00:00'),
(20, 'Linux Kernel 7.0 Released with Improved Rust Support', 'Meruert Kunakova', 6, 'published', 'Linus Torvalds has announced the release of Linux kernel 7.0, featuring greatly expanded Rust language support for writing kernel drivers, which is expected to reduce memory safety bugs.', 'linux7.png', 3560, '2026-01-21 10:00:00', '2026-01-21 10:00:00'),
(21, 'PostgreSQL 18 Adds Native Columnar Storage Engine', 'Aibek Seitkali', 6, 'published', 'PostgreSQL 18 introduces an optional columnar storage engine, enabling analytical workloads to run significantly faster without requiring a separate data warehouse solution.', 'postgres18.png', 2980, '2026-02-22 10:00:00', '2026-02-22 10:00:00'),
(22, 'GNOME 50 Redesigns the Linux Desktop from Scratch', 'Dinara Akhmetova', 6, 'published', 'GNOME 50 ships with a completely redesigned desktop shell built on GTK5, featuring improved HiDPI support, a new notification system, and deeply integrated search powered by a local AI model.', 'gnome50.png', 1670, '2026-03-23 10:00:00', '2026-03-23 10:00:00'),
(23, 'VS Code Forks Surge as Microsoft Restricts Extension APIs', 'Nursultan Nurmagambetov', 6, 'archived', 'Following Microsofts decision to restrict certain extension APIs in VS Code, open-source forks such as VSCodium and Code - OSS have seen a sharp surge in downloads and community contributions.', 'vscode_fork.png', 4230, '2026-04-24 10:00:00', '2026-04-24 10:00:00'),
(24, 'Global Developer Salaries Rise 12% in 2026 Report', 'Madina Bekova', 7, 'published', 'Stack Overflows 2026 Developer Survey reveals a 12% average salary increase for software developers globally, with AI and cloud specializations commanding the largest premiums.', 'dev_salaries.png', 5480, '2026-01-25 10:00:00', '2026-01-25 10:00:00'),
(25, 'Remote Work Remains Dominant for Tech Professionals', 'Yerlan Sultanov', 7, 'published', 'A new survey of 45,000 developers shows that over 68% continue to work fully remotely or in hybrid arrangements, with most citing flexibility as the primary factor in job satisfaction.', 'remote_work.png', 3120, '2026-02-26 10:00:00', '2026-02-26 10:00:00'),
(26, 'Top 10 Programming Languages to Learn in 2026', 'Zarina Karimova', 7, 'published', 'Our annual ranking of in-demand programming languages places Python, TypeScript, and Rust at the top, reflecting growing demand in AI development, web engineering, and systems programming.', 'prog_languages.png', 7850, '2026-03-27 10:00:00', '2026-03-27 10:00:00'),
(27, 'IT Career Fair 2026 Breaks Attendance Records in Astana', 'Damir Tulegenov', 7, 'published', 'The IT Career Fair 2026 held in Astana attracted over 12,000 visitors and 120 exhibiting companies, setting a new record for the largest technology employment event in Central Asia.', 'career_fair.png', 2660, '2026-04-28 10:00:00', '2026-04-28 10:00:00'),
(28, 'NVIDIA Blackwell B200 GPU Benchmark Results Leak', 'Aigerim Abdullina', 8, 'published', 'Early benchmark results for NVIDIAs Blackwell B200 GPU have leaked online, showing a 3x improvement in AI inference throughput compared to the previous H100 generation.', 'b200_gpu.png', 4990, '2026-01-01 10:00:00', '2026-01-01 10:00:00'),
(29, 'Apple Silicon M5 Pro Achieves Desktop-Class Performance', 'Ruslan Ospanov', 8, 'published', 'Apple has unveiled the M5 Pro chip, which benchmarks reveal to be on par with high-end desktop CPUs in multi-core workloads while consuming a fraction of the power.', 'm5_pro.png', 4210, '2026-02-02 10:00:00', '2026-02-02 10:00:00'),
(30, 'Quantum Computer Achieves 1000-Qubit Milestone', 'Saule Dzhaksybekova', 8, 'published', 'IBM has announced a 1000-qubit quantum processor, crossing a symbolic threshold that researchers say marks the beginning of practical quantum advantage for select optimization problems.', 'quantum_1000.png', 3780, '2026-03-03 10:00:00', '2026-03-03 10:00:00');
